const locTags=a=>state.lang==='en'?(a.en?.tags||[]):(a.tags||[]);
const visibleSeries=()=>state.lang==='en'?series.filter(s=>s.status!=='draft'&&s.title_en):series.filter(s=>s.status!=='draft');
const locSeries=(s,k)=>state.lang==='en'?(s?.[`${k}_en`]||s?.[k]||''):(s?.[k]||'');
const visibleSections=()=>sections.filter(s=>s.visible!==false).sort((a,b)=>(a.sortOrder||100)-(b.sortOrder||100));
const sectionForArticle=a=>sections.find(s=>s.id===a.sectionId)||null;
const locSection=(s,k='title')=>state.lang==='en'?(s?.[`${k}_en`]||s?.[k]||''):(s?.[k]||'');
const sectionURL=s=>`section.html?section=${encodeURIComponent(typeof s==='string'?s:s.slug)}`;
const sectionArticles=s=>byDate(articles.filter(a=>a.sectionId===s.id));
const editorialMeta=a=>{const sec=sectionForArticle(a);return [sec?locSection(sec):'',categoryLabel(a)].filter(Boolean).join(' · ')};
const seriesForArticle=a=>{const sr=series.find(s=>(a.seriesSlug&&s.slug===a.seriesSlug)||(a.seriesId&&s.id===a.seriesId));return state.lang==='en'&&sr&&!sr.title_en?null:sr};
const seriesMembers=s=>visibleArticles(articles.filter(a=>(a.seriesSlug&&a.seriesSlug===s.slug)||(a.seriesId&&s.id&&a.seriesId===s.id))).sort((a,b)=>(Number(a.seriesOrder)||9999)-(Number(b.seriesOrder)||9999)||String(a.date||'').localeCompare(String(b.date||'')));
const seriesURL=s=>`series.html?series=${encodeURIComponent(s.slug)}`;
const categoryLabel=a=>({news:t('categoryNews'),report:t('categoryReport'),article:t('categoryArticle'),training:t('categoryTraining')})[categoryOf(a)];
const byDate=(xs=articles)=>[...visibleArticles(xs)].sort((a,b)=>String(b.publishedAt||b.date||'').localeCompare(String(a.publishedAt||a.date||'')));
const mediaURL=(url,stamp='')=>{if(!url)return '';if(!/^https:\/\/[^/]*supabase\.co\/storage\/v1\/object\/public\//i.test(url)||!stamp)return url;const sep=url.includes('?')?'&':'?';return `${url}${sep}v=${encodeURIComponent(String(stamp))}`};
const cover=a=>{const img=a.image||`assets/covers/${a.slug}.svg`;if(state.lang==='en'&&/\.svg(?:$|\?)/i.test(img))return `assets/covers/default-${categoryOf(a)}.svg`;return mediaURL(img,a.updatedAt)};
const savedSet=()=>new Set(store.get('dana-saved',[]));
const isSaved=s=>savedSet().has(s);
function setSaved(s,on){const x=savedSet();on?x.add(s):x.delete(s);store.set('dana-saved',[...x]);updateSavedCount();}
const formatDate=d=>{if(!d)return'';const x=new Date(`${d}T12:00:00`);return new Intl.DateTimeFormat(state.lang==='ar'?'ar-SA':'en-GB',{day:'numeric',month:'long',year:'numeric'}).format(x)};
const readingTime=a=>Math.max(1,Math.ceil(locBody(a).join(' ').split(/\s+/).filter(Boolean).length/(state.lang==='ar'?170:220)));
function titleWords(v){return String(v||'').toLocaleLowerCase(state.lang==='ar'?'ar':'en').replace(/[\u064B-\u065F\u0670]/g,'').replace(/[^\p{L}\p{N}]+/gu,' ').trim().split(/\s+/).filter(Boolean)}
function titleMatches(a,q){const needleWords=titleWords(q);if(!needleWords.length)return true;const words=titleWords(loc(a,'title'));return words.some((_,i)=>needleWords.every((nw,j)=>words[i+j]?.startsWith(nw)));}
function articleURL(a){return `index.html?article=${encodeURIComponent(a.slug)}`}
function canonicalArticleURL(a){return `${PUBLIC_SITE}index.html?article=${encodeURIComponent(a.slug)}`}
function qrCodeURL(a){return `${QR_ENDPOINT}?url=${encodeURIComponent(canonicalArticleURL(a))}`}
function printProvenance(a){const year=new Date().getFullYear(),url=canonicalArticleURL(a),label=state.lang==='ar'?'نُشر أصلًا عبر منصة دانه بالجهر':'Originally published on Dana Baljher';return `<div class="print-brand-top"><b>${state.lang==='ar'?'دانه بالجهر':'DANA BALJHER'}</b><span>${state.lang==='ar'?'منصة تحريرية مستقلة':'Independent Editorial Platform'}</span></div><div class="print-watermark">DANA BALJHER · دانه بالجهر</div><div class="print-provenance"><div class="print-provenance-copy"><strong>${esc(label)}</strong><span>${esc(url)}</span><small>© ${year} ${state.lang==='ar'?'دانه بالجهر · جميع الحقوق محفوظة':'Dana Baljher · All rights reserved'}</small></div><img src="${esc(qrCodeURL(a))}" alt="QR · ${esc(url)}" crossorigin="anonymous"></div>`}
function pageURL(cat){return {news:'news.html',report:'reports.html',article:'essays.html',series:'series.html',training:'experience.html',data:'data.html',archive:'archive.html'}[cat]||'index.html'}
function applyPreferences(){document.documentElement.lang=state.lang;document.documentElement.dir=state.lang==='ar'?'rtl':'ltr';document.documentElement.dataset.theme=state.theme;document.documentElement.style.setProperty('--ui-scale',state.scale);$$('[data-name]').forEach(n=>n.textContent=t('name'));$$('[data-portfolio]').forEach(n=>n.textContent=t('portfolio'));updateSavedCount();}
function updateSavedCount(){const n=savedSet().size;$$('[data-saved-count]').forEach(x=>x.textContent=n)}
function renderRibbon(){if(!ribbon)return;const secItems=visibleSections().map(s=>[`section-${s.slug}`,locSection(s),sectionURL(s),sectionArticles(s).length]);const items=[['selected',t('latest'),'index.html#now',Math.min(9,visibleArticles().length)],...secItems,['series',t('series'),'series.html',visibleSeries().length],['archive',t('danaWork'),'archive.html',visibleArticles().length]];ribbon.innerHTML=items.map(([id,label,url,n])=>`<a class="ribbon-link ${activeRibbon(id)?'active':''}" href="${url}"><span>${esc(label)}</span><b>${n}</b></a>`).join('')}
function activeRibbon(id){if(page==='archive')return id==='archive';if(page==='series')return id==='series';if(page==='section'){const slug=new URLSearchParams(location.search).get('section');return id===`section-${slug}`}return id==='selected'&&location.hash==='#now'}
function arrow(){return `<span class="arrow" aria-hidden="true">${state.lang==='ar'?'←':'→'}</span>`}
function homeBack(){return `<a class="page-back-home" href="index.html">${arrow()}<span>${esc(t('home'))}</span></a>`}
function isFresh(a){const raw=a.publishedAt||a.date;if(!raw)return false;const d=new Date(raw);return Number.isFinite(d.getTime())&&(Date.now()-d.getTime())>=0&&(Date.now()-d.getTime())<=36*60*60*1000}
